/bin/bash -lc "uname -m; sysctl -n machdep.cpu.brand_string 2>/dev/null || true; system_profiler SPDisplaysDataType 2>/dev/null | sed -n '1,100p'; python3 - <<'PY'
mods=['tensorflow','tensorflow_macos','torch','h5py','numpy']
for m in mods:
 try:
  x=__import__(m); print(m,getattr(x,'__version__','ok'))
 except Exception as e: print(m,'MISSING',repr(e))
PY
python3 -m pip list | grep -Ei 'tensorflow|keras|metal|torch|h5py|numpy' || true"
